#include <iostream>
using namespace std;

int main() {
    int choice = 3;

    switch (choice) {
        case 1:
            cout << "三文鱼喵" << endl;
            break;
        case 2:
            cout << "秋刀鱼喵" << endl;
            break;
        case 3:
            cout << "鳕鱼喵" << endl;
